const menus={Haircuts:[["Women’s haircut and style","from $80"],["Men’s haircut","from $50"],["Fade haircut","from $60"],["Girls’ cut","from $60"],["Boys’ cut","from $50"],["Wash and blow-dry","from $50"]],Colour:[["Root touch-up","from $80"],["Full head colour","from $110"],["INOA root touch-up","from $90"],["INOA full head colour","from $120"],["10-minute root touch-up","from $90"],["Men’s shade colour","$50"],["Tailored colour restoration","Consultation"]],Highlights:[["Half-head highlights","from $190"],["Full-head highlights","from $230"],["Toner","from $50"],["Balayage","from $250"],["Ombré","from $230"]],Treatments:[["Keratin straightening","from $400"],["Hair Botox","from $200"],["Permanent wave · consultation required","from $200"],["Spiral perm","Consultation"],["Olaplex treatment","$45"],["Deep conditioning treatment","$35"],["Metal detox treatment","$45"]],Styling:[["Formal updo","from $100"],["Natural hair extensions","Enquire"],["Tape-in extensions","Enquire"],["Fusion extensions","Enquire"],["Microlink extensions","Enquire"],["Clip-in extensions","Enquire"]],Beauty:[["Eyebrow tinting","$25"],["Full-face threading, including brows","$50"],["Eyebrow threading","$25"],["Upper lip","$15"],["Chin and neck","$18"],["Day makeup","$60"],["Evening makeup","$75"],["Special occasion makeup","$120"],["Eyelash extension","$30"],["Eyelash extensions · 3 weeks","$150"]],Packages:[["Colouring + blow-dry","$135"],["5 wash-and-blow-dry visits · ask for details","from $150"],["Bridal: wash, blow-dry, updo & makeup","from $499"]]};
const categories=document.querySelector('.categories');Object.keys(menus).forEach((name,i)=>{const b=document.createElement('button');b.type='button';b.role='tab';b.id='tab-'+i;b.setAttribute('aria-controls','price-panel');b.textContent=name;b.addEventListener('click',()=>select(name));categories.appendChild(b)});
function select(name){const buttons=[...categories.children];buttons.forEach(b=>{const selected=b.textContent===name;b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1;if(selected)document.querySelector('#price-panel').setAttribute('aria-labelledby',b.id)});document.querySelector('#price-list').replaceChildren(...menus[name].map(([label,price])=>{const row=document.createElement('div');row.className='price-row';const l=document.createElement('span'),p=document.createElement('span');l.textContent=label;p.textContent=price;row.append(l,p);return row}))}
categories.addEventListener('keydown',e=>{const buttons=[...categories.children];let i=buttons.indexOf(document.activeElement);if(i<0)return;if(['ArrowRight','ArrowDown','ArrowLeft','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();i=e.key==='Home'?0:e.key==='End'?buttons.length-1:(i+(['ArrowRight','ArrowDown'].includes(e.key)?1:-1)+buttons.length)%buttons.length;select(buttons[i].textContent);buttons[i].focus()}});select('Haircuts');document.querySelectorAll('[data-category]').forEach(a=>a.addEventListener('click',()=>select(a.dataset.category)));
const toggle=document.querySelector('.menu-toggle'),nav=document.querySelector('nav');toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Close navigation':'Open navigation');nav.classList.toggle('open',open)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');toggle.setAttribute('aria-expanded','false')}));document.getElementById('year').textContent=new Date().getFullYear();
